#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9
LIVE_REF="twvrftjwwwiliywjdtjo"

# copy_sql FILE puts FILE's text on the clipboard, or says where to copy it from.
copy_sql() {
  if command -v clip.exe >/dev/null 2>&1 || command -v clip >/dev/null 2>&1; then
    { clip.exe 2>/dev/null || clip; } < "$1"
    note "The SQL is on your clipboard."
  else
    note "Copy the SQL from: $1"
  fi
}

# Open links in Chrome when it is installed (the owner signs in to Supabase there), not the default browser.
CHROME="/c/Program Files/Google/Chrome/Application/chrome.exe"
if [[ -x "$CHROME" ]]; then
  open_url() {
    printf '  %s↗ opening in Chrome%s %s\n' "$GREEN" "$RESET" "$1"
    "$CHROME" "$1" >/dev/null 2>&1 &
  }
fi

# Run from the repo root so .env lands next to package.json, and never let it be committed.
cd "$(dirname "$0")/.."
if ! git check-ignore -q .env; then
  warn ".env is not in .gitignore. Add it before running this wizard."; exit 1
fi

# Read-only: prints the CREATE TABLE, constraints, RLS switch and policies of public.messages.
SCHEMA_QUERY="with t as (select 'public.messages'::regclass as rel), \
cols as (select string_agg(format('%I %s%s%s', a.attname, format_type(a.atttypid, a.atttypmod), \
case when a.attidentity in ('a','d') or pg_get_expr(d.adbin, d.adrelid) like 'nextval(%' then ' generated by default as identity' \
when d.adbin is not null and a.attgenerated = '' then ' default ' || pg_get_expr(d.adbin, d.adrelid) else '' end, \
case when a.attnotnull then ' not null' else '' end), ', ' order by a.attnum) as body \
from pg_attribute a join t on a.attrelid = t.rel left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum \
where a.attnum > 0 and not a.attisdropped), \
cons as (select string_agg(format('alter table public.messages add constraint %I %s;', c.conname, pg_get_constraintdef(c.oid)), ' ' order by c.conname) as body \
from pg_constraint c join t on c.conrelid = t.rel where c.contype in ('p','u','c')), \
pols as (select string_agg(format('create policy %I on public.messages as %s for %s to %s%s%s;', policyname, lower(permissive), lower(cmd), \
array_to_string(roles, ', '), coalesce(' using (' || qual || ')', ''), coalesce(' with check (' || with_check || ')', '')), ' ' order by policyname) as body \
from pg_policies where schemaname = 'public' and tablename = 'messages') \
select 'create table public.messages (' || cols.body || '); ' || coalesce(cons.body, '') || \
case when (select relrowsecurity from pg_class where oid = 'public.messages'::regclass) then ' alter table public.messages enable row level security; ' else ' ' end || \
coalesce(pols.body, '') as ddl from cols, cons, pols;"

banner "Test Supabase project for GermanCourses (#5)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the test project"
say "A separate, free Supabase project that only automated tests use."
say "Tests will create fake bookings there, so it must never be the live project."
open_url "https://supabase.com/dashboard/new"
step "Pick your organization (the free plan is fine)."
step "Project name: germancourses-test"
step "Database password: click Generate, and save it in your password manager."
step "Region: Central EU (Frankfurt), the closest to Egypt."
step "Click 'Create new project' and wait until it says the project is ready."
step "Copy the browser address. It looks like supabase.com/dashboard/project/abcdefghijklmnopqrst"
while true; do
  ask SUPABASE_TEST_PROJECT_REF "Paste the address or just the 20-letter project ID:"
  ref=$(printf '%s' "$SUPABASE_TEST_PROJECT_REF" | grep -oE '[a-z]{20}' | head -1 || true)
  if [[ -z "$ref" ]]; then warn "No 20-letter project ID found in that. Try again."; continue; fi
  if [[ "$ref" == "$LIVE_REF" ]]; then warn "That is the LIVE project. Create a new one and paste its ID."; continue; fi
  break
done
REF="$ref"
write_env SUPABASE_TEST_PROJECT_REF "$REF"
write_env SUPABASE_TEST_URL "https://$REF.supabase.co"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Copy the structure of the live messages table"
say "This reads only the table definition (columns and rules), never any message."
printf '%s' "$SCHEMA_QUERY" > "$PWD/.wizard-schema-query.sql"
copy_sql "$PWD/.wizard-schema-query.sql"
open_url "https://supabase.com/dashboard/project/$LIVE_REF/sql/new"
step "This is the LIVE project's SQL Editor. Paste the query (Ctrl+V) and click Run."
step "The result is one row with one long text in the 'ddl' column."
step "Click that cell and copy its whole text (right-click → Copy cell content, or Ctrl+C)."
warn "Don't run anything else in the live project."
pause "Press Enter once the result is copied"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the messages table in the test project"
open_url "https://supabase.com/dashboard/project/$REF/sql/new"
step "Check the project name at the top says germancourses-test, not the live one."
step "Paste the text you copied (it starts with 'create table public.messages') and click Run."
step "It should say 'Success. No rows returned'."
note "If it errors, copy the error message and stop here (Ctrl-C) so it can be fixed."
rm -f "$PWD/.wizard-schema-query.sql"
pause "Press Enter once it ran successfully"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Add the SPEC-2 tables (accounts, courses, bookings)"
say "The same changes the live project gets at launch: profiles, courses, orders,"
say "quiz results, message status and the booking-email trigger."
SPEC2_SQL="$PWD/.wizard-spec2.sql"
{ cat supabase/migrations/*.sql
  printf "\n-- This project's booking-email address (see the order-emails trigger above).\n"
  printf "select vault.create_secret('https://%s.supabase.co/functions/v1/order-emails', 'order_emails_url')\n" "$REF"
  printf "where not exists (select 1 from vault.secrets where name = 'order_emails_url');\n"
} > "$SPEC2_SQL"
copy_sql "$SPEC2_SQL"
open_url "https://supabase.com/dashboard/project/$REF/sql/new"
step "Check the project name at the top says germancourses-test."
step "Paste (Ctrl+V) and click Run. It should end with a 'Success' message."
note "If Supabase asks you to confirm before running, confirm: this is the test project."
note "If it errors, copy the error message and stop here (Ctrl-C) so it can be fixed."
pause "Press Enter once it ran successfully"
rm -f "$SPEC2_SQL"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Copy the test project's public key"
open_url "https://supabase.com/dashboard/project/$REF/settings/api-keys"
step "Under 'Publishable key', copy the key that starts with sb_publishable_"
note "This key is public by design: the same kind is already in the site's pages."
while true; do
  ask SUPABASE_TEST_PUBLISHABLE_KEY "Paste the publishable key:"
  [[ "$SUPABASE_TEST_PUBLISHABLE_KEY" == sb_publishable_* ]] && break
  warn "That doesn't start with sb_publishable_. Copy the Publishable key, not the Secret key."
done
write_env SUPABASE_TEST_PUBLISHABLE_KEY "$SUPABASE_TEST_PUBLISHABLE_KEY"
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Keep public sign-ups on"
say "Students make their own accounts (SPEC-2), so sign-ups must stay ON."
open_url "https://supabase.com/dashboard/project/$REF/auth/providers"
step "Find the setting 'Allow new users to sign up' (usually under User Signups"
step "on Authentication → Sign In / Providers) and make sure it is ON."
step "Leave 'Confirm email' ON too: students confirm their email before signing in."
step "Click Save if a Save button appears."
note "Menu names change sometimes. Stage 9 checks that sign-ups are really on."
pause "Press Enter once sign-ups are on"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Create the test Admin user"
open_url "https://supabase.com/dashboard/project/$REF/auth/users"
step "Click 'Add user' → 'Create new user'."
step "Enter an email you control and a strong password."
step "Tick 'Auto Confirm User', then click 'Create user'."
note "This account exists only in the test project. Don't reuse Frau Asmaa's real password."
ask SUPABASE_TEST_ADMIN_EMAIL "Email you used:"
ask_secret SUPABASE_TEST_ADMIN_PASSWORD "Password you used (hidden):"
write_env SUPABASE_TEST_ADMIN_EMAIL "$SUPABASE_TEST_ADMIN_EMAIL"
write_env SUPABASE_TEST_ADMIN_PASSWORD "$SUPABASE_TEST_ADMIN_PASSWORD"
say "Now make this user the Admin. Only SQL can do this, so nobody can make themselves Admin."
ADMIN_SQL="$PWD/.wizard-admin.sql"
printf "update auth.users set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb) || '{\"role\": \"admin\"}'\nwhere email = '%s';\n" \
  "${SUPABASE_TEST_ADMIN_EMAIL//\'/\'\'}" > "$ADMIN_SQL"
copy_sql "$ADMIN_SQL"
open_url "https://supabase.com/dashboard/project/$REF/sql/new"
step "Check the project name says germancourses-test, paste (Ctrl+V) and click Run."
